import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { motion } from 'motion/react';
import { BarChart3, Check, Loader2, ShieldCheck, Users } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { appToast } from '../../lib/feedback';

type Poll = {
  question: string;
  options: string[];
  allowMultiple?: boolean;
};

type Vote = {
  voter_id: string;
  option_index: number;
};

export function ChatPollCard({
  messageId,
  chatId,
  userId,
  poll,
}: {
  messageId: string;
  chatId: string;
  userId?: string;
  poll: Poll;
}) {
  const [votes, setVotes] = useState<Vote[]>([]);
  const [busyIndex, setBusyIndex] = useState<number | null>(null);

  const loadVotes = useCallback(async () => {
    const { data, error } = await supabase
      .from('chat_poll_votes')
      .select('voter_id,option_index')
      .eq('message_id', messageId);
    if (!error) setVotes((data || []) as Vote[]);
  }, [messageId]);

  useEffect(() => {
    void loadVotes();
    const channel = supabase
      .channel(`chat-poll:${messageId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'chat_poll_votes',
        filter: `message_id=eq.${messageId}`,
      }, () => void loadVotes())
      .subscribe();
    return () => {
      void supabase.removeChannel(channel);
    };
  }, [loadVotes, messageId]);

  const voterCount = useMemo(() => new Set(votes.map((vote) => vote.voter_id)).size, [votes]);
  const selected = useMemo(() =>
    new Set(votes.filter((vote) => vote.voter_id === userId).map((vote) => vote.option_index)),
  [userId, votes]);
  const counts = poll.options.map((_, optionIndex) =>
    votes.filter((vote) => vote.option_index === optionIndex).length,
  );
  const maxCount = Math.max(...counts, 1);

  const vote = async (optionIndex: number) => {
    if (!userId || busyIndex !== null) return;
    setBusyIndex(optionIndex);
    try {
      if (selected.has(optionIndex)) {
        const { error } = await supabase
          .from('chat_poll_votes')
          .delete()
          .eq('message_id', messageId)
          .eq('voter_id', userId)
          .eq('option_index', optionIndex);
        if (error) throw error;
      } else {
        if (!poll.allowMultiple && selected.size > 0) {
          const { error } = await supabase
            .from('chat_poll_votes')
            .delete()
            .eq('message_id', messageId)
            .eq('voter_id', userId);
          if (error) throw error;
        }
        const { error } = await supabase
          .from('chat_poll_votes')
          .insert({
            message_id: messageId,
            chat_id: chatId,
            voter_id: userId,
            option_index: optionIndex,
          });
        if (error) throw error;
      }
      await loadVotes();
    } catch (reason) {
      console.error('Poll vote could not be saved:', reason);
      appToast('Your vote could not be saved.');
    } finally {
      setBusyIndex(null);
    }
  };

  return (
    <div className="chat-poll-card rounded-[22px] border border-white/10 bg-black/15 p-3.5">
      <div className="flex items-start gap-3">
        <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-violet-400/15 text-violet-200">
          <BarChart3 className="h-5 w-5" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-[10px] font-bold uppercase tracking-[0.14em] opacity-50">Poll</p>
          <p className="mt-1 text-[14px] font-bold leading-5">{poll.question}</p>
        </div>
      </div>

      <div className="mt-3 space-y-2">
        {poll.options.map((option, optionIndex) => {
          const count = counts[optionIndex];
          const isSelected = selected.has(optionIndex);
          return (
            <button
              type="button"
              key={`${option}-${optionIndex}`}
              onClick={() => void vote(optionIndex)}
              disabled={!userId || busyIndex !== null}
              className={`relative flex min-h-11 w-full items-center overflow-hidden rounded-xl border px-3 text-left text-xs font-semibold transition ${
                isSelected
                  ? 'border-violet-300/35 bg-violet-300/10'
                  : 'border-white/10 bg-white/[0.035] hover:border-white/20'
              }`}
            >
              <motion.span
                initial={false}
                animate={{ width: votes.length ? `${Math.max(5, (count / maxCount) * 100)}%` : '0%' }}
                className="absolute inset-y-0 left-0 bg-white/[0.055]"
              />
              <span className="relative min-w-0 flex-1 truncate">{option}</span>
              <span className="relative ml-3 flex shrink-0 items-center gap-1.5 opacity-60">
                {busyIndex === optionIndex
                  ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  : isSelected
                    ? <Check className="h-3.5 w-3.5" />
                    : null}
                {count}
              </span>
            </button>
          );
        })}
      </div>

      <div className="mt-3 flex items-center justify-between gap-3 text-[10px] opacity-50">
        <span className="flex items-center gap-1.5">
          <Users className="h-3.5 w-3.5" /> {voterCount} {voterCount === 1 ? 'voter' : 'voters'}
        </span>
        <span className="flex items-center gap-1.5">
          <ShieldCheck className="h-3.5 w-3.5" />
          {poll.allowMultiple ? 'Multiple choices' : 'One choice'}
        </span>
      </div>
    </div>
  );
}
