import { useEffect, useState } from 'react';
import { BellOff, BellRing, Laptop2, Loader2, MessageCircle, Users } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import {
  getChatPushState,
  setChatPushNotifications,
  type ChatPushState,
} from '../../hooks/useNotifications';
import { appToast } from '../../lib/feedback';
import { BottomSheetModal } from '../ui/BottomSheetModal';

type Preferences = {
  desktop_push_enabled: boolean;
  direct_messages: boolean;
  group_messages: boolean;
  public_dms: boolean;
};

type Props = {
  isOpen: boolean;
  onClose: () => void;
  userId?: string;
  onStateChange?: (state: ChatPushState) => void;
};

const defaults: Preferences = {
  desktop_push_enabled: false,
  direct_messages: true,
  group_messages: true,
  public_dms: true,
};

const Toggle = ({
  checked,
  onChange,
  label,
  description,
  icon: Icon,
  disabled,
}: {
  checked: boolean;
  onChange: (checked: boolean) => void;
  label: string;
  description: string;
  icon: typeof MessageCircle;
  disabled?: boolean;
}) => (
  <div className={`flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.035] p-3.5 ${disabled ? 'opacity-45' : ''}`}>
    <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white/[0.06] text-gray-300">
      <Icon className="h-4.5 w-4.5" />
    </span>
    <span className="min-w-0 flex-1">
      <span className="block text-sm font-semibold text-white">{label}</span>
      <span className="mt-0.5 block text-xs leading-5 text-gray-500">{description}</span>
    </span>
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      disabled={disabled}
      onClick={() => onChange(!checked)}
      className={`relative h-7 w-12 shrink-0 rounded-full transition-colors ${
        checked ? 'bg-blue-500' : 'bg-white/10'
      }`}
    >
      <span className={`absolute top-1 h-5 w-5 rounded-full bg-white shadow transition-transform ${
        checked ? 'translate-x-6' : 'translate-x-1'
      }`} />
    </button>
  </div>
);

export function ChatNotificationSettingsModal({
  isOpen,
  onClose,
  userId,
  onStateChange,
}: Props) {
  const [preferences, setPreferences] = useState<Preferences>(defaults);
  const [pushState, setPushState] = useState<ChatPushState | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!isOpen || !userId) return;
    let active = true;
    setLoading(true);
    void Promise.all([
      getChatPushState(userId),
      supabase
        .from('chat_notification_preferences')
        .select('desktop_push_enabled,direct_messages,group_messages,public_dms')
        .eq('user_id', userId)
        .maybeSingle(),
    ]).then(([state, result]) => {
      if (!active) return;
      setPushState(state);
      setPreferences({ ...defaults, ...(result.data || {}), desktop_push_enabled: state.enabled });
      onStateChange?.(state);
    }).finally(() => active && setLoading(false));
    return () => {
      active = false;
    };
  }, [isOpen, userId]);

  const setMaster = async (enabled: boolean) => {
    if (!userId || saving) return;
    setSaving(true);
    try {
      const next = await setChatPushNotifications(userId, enabled);
      setPushState(next);
      setPreferences((current) => ({ ...current, desktop_push_enabled: next.enabled }));
      onStateChange?.(next);
      if (enabled && !next.configured) {
        appToast('Desktop Push still needs a server key before it can be enabled.');
      } else if (enabled && next.permission === 'denied') {
        appToast('Allow notifications in your browser settings, then try again.');
      } else {
        appToast(next.enabled ? 'Desktop chat notifications are on.' : 'Desktop chat notifications are off.');
      }
    } catch (error) {
      console.error('Chat push preference could not be changed:', error);
      appToast(error instanceof Error ? error.message : 'Chat notifications could not be changed.');
    } finally {
      setSaving(false);
    }
  };

  const setPreference = async (
    key: 'direct_messages' | 'group_messages' | 'public_dms',
    enabled: boolean,
  ) => {
    if (!userId) return;
    const previous = preferences;
    const next = { ...preferences, [key]: enabled };
    setPreferences(next);
    const { error } = await supabase
      .from('chat_notification_preferences')
      .upsert({ user_id: userId, [key]: enabled }, { onConflict: 'user_id' });
    if (error) {
      setPreferences(previous);
      appToast('This notification preference could not be saved.');
    }
  };

  const masterEnabled = pushState?.enabled === true;

  return (
    <BottomSheetModal
      isOpen={isOpen}
      onClose={onClose}
      title="Chat notifications"
      maxWidth="max-w-lg"
    >
      <div className="space-y-4 p-5 md:p-6">
        {loading ? (
          <div className="flex min-h-48 items-center justify-center">
            <Loader2 className="h-5 w-5 animate-spin text-gray-500" />
          </div>
        ) : (
          <>
            <div className="overflow-hidden rounded-[22px] border border-white/10 bg-gradient-to-br from-blue-500/15 via-white/[0.035] to-transparent p-5">
              <div className="flex items-start gap-4">
                <span className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl ${
                  masterEnabled ? 'bg-blue-500 text-white' : 'bg-white/[0.07] text-gray-400'
                }`}>
                  {masterEnabled ? <BellRing className="h-5 w-5" /> : <BellOff className="h-5 w-5" />}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-base font-bold text-white">Desktop Push</span>
                  <span className="mt-1 block text-xs leading-5 text-gray-400">
                    Get a notification even when Wersee is in the background. Message contents stay hidden for encrypted chats.
                  </span>
                </span>
                <button
                  type="button"
                  role="switch"
                  aria-checked={masterEnabled}
                  disabled={saving || pushState?.supported === false}
                  onClick={() => void setMaster(!masterEnabled)}
                  className={`relative mt-1 h-7 w-12 shrink-0 rounded-full transition-colors ${
                    masterEnabled ? 'bg-blue-500' : 'bg-white/10'
                  }`}
                >
                  <span className={`absolute top-1 h-5 w-5 rounded-full bg-white shadow transition-transform ${
                    masterEnabled ? 'translate-x-6' : 'translate-x-1'
                  }`} />
                </button>
              </div>
              {pushState?.supported === false && (
                <p className="mt-4 rounded-xl bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
                  This browser does not support desktop push notifications.
                </p>
              )}
              {pushState?.permission === 'denied' && (
                <p className="mt-4 rounded-xl bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
                  Notifications are blocked in this browser. Enable them in the site permissions first.
                </p>
              )}
            </div>

            <div className="space-y-2.5">
              <Toggle
                checked={preferences.direct_messages}
                onChange={(value) => void setPreference('direct_messages', value)}
                label="Direct messages"
                description="Messages from people you chat with."
                icon={MessageCircle}
                disabled={!masterEnabled}
              />
              <Toggle
                checked={preferences.group_messages}
                onChange={(value) => void setPreference('group_messages', value)}
                label="Groups and teams"
                description="New messages in shared conversations."
                icon={Users}
                disabled={!masterEnabled}
              />
              <Toggle
                checked={preferences.public_dms}
                onChange={(value) => void setPreference('public_dms', value)}
                label="Public DMs"
                description="New contact messages and guest replies."
                icon={Laptop2}
                disabled={!masterEnabled}
              />
            </div>
          </>
        )}
      </div>
    </BottomSheetModal>
  );
}
