import { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../context/AuthContext';

const VAPID_PUBLIC_KEY = (
  import.meta.env.VITE_WEB_PUSH_PUBLIC_KEY
  || import.meta.env.VITE_FIREBASE_VAPID_KEY
  || ''
) as string;

export type ChatPushState = {
  supported: boolean;
  permission: NotificationPermission | 'unsupported';
  enabled: boolean;
  configured: boolean;
};

const applicationServerKey = (value: string) => {
  const normalizedKey = value.replace(/-/g, '+').replace(/_/g, '/');
  const paddedKey = normalizedKey.padEnd(Math.ceil(normalizedKey.length / 4) * 4, '=');
  return Uint8Array.from(atob(paddedKey), (character) => character.charCodeAt(0));
};

const getRegistration = async () => {
  const registration = await navigator.serviceWorker.register('/sw.js', { scope: '/' });
  await navigator.serviceWorker.ready;
  return registration;
};

export async function getChatPushState(userId: string): Promise<ChatPushState> {
  const supported = (
    typeof window !== 'undefined'
    && 'Notification' in window
    && 'serviceWorker' in navigator
    && 'PushManager' in window
  );
  if (!supported) {
    return { supported: false, permission: 'unsupported', enabled: false, configured: Boolean(VAPID_PUBLIC_KEY) };
  }

  const { data } = await supabase
    .from('chat_notification_preferences')
    .select('desktop_push_enabled')
    .eq('user_id', userId)
    .maybeSingle();

  return {
    supported: true,
    permission: Notification.permission,
    enabled: data?.desktop_push_enabled === true && Notification.permission === 'granted',
    configured: Boolean(VAPID_PUBLIC_KEY),
  };
}

export async function setChatPushNotifications(
  userId: string,
  enabled: boolean,
): Promise<ChatPushState> {
  if (
    typeof window === 'undefined'
    || !('Notification' in window)
    || !('serviceWorker' in navigator)
    || !('PushManager' in window)
  ) {
    return { supported: false, permission: 'unsupported', enabled: false, configured: Boolean(VAPID_PUBLIC_KEY) };
  }

  if (!enabled) {
    await Promise.all([
      supabase
        .from('chat_notification_preferences')
        .upsert({ user_id: userId, desktop_push_enabled: false }, { onConflict: 'user_id' }),
      supabase
        .from('push_subscriptions')
        .update({ enabled: false })
        .eq('user_id', userId),
    ]);
    return {
      supported: true,
      permission: Notification.permission,
      enabled: false,
      configured: Boolean(VAPID_PUBLIC_KEY),
    };
  }

  const permission = await Notification.requestPermission();
  if (permission !== 'granted') {
    return { supported: true, permission, enabled: false, configured: Boolean(VAPID_PUBLIC_KEY) };
  }
  if (!VAPID_PUBLIC_KEY) {
    return { supported: true, permission, enabled: false, configured: false };
  }

  const registration = await getRegistration();
  const expectedKey = applicationServerKey(VAPID_PUBLIC_KEY);
  let subscription = await registration.pushManager.getSubscription();
  const currentKey = subscription?.options.applicationServerKey
    ? new Uint8Array(subscription.options.applicationServerKey)
    : null;
  const keyMatches = currentKey?.length === expectedKey.length
    && currentKey.every((byte, index) => byte === expectedKey[index]);
  if (subscription && !keyMatches) {
    await subscription.unsubscribe();
    subscription = null;
  }
  subscription = subscription || await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: expectedKey as BufferSource,
    });
  const subscriptionJson = subscription.toJSON();
  const authKey = subscriptionJson.keys?.auth;
  const p256dhKey = subscriptionJson.keys?.p256dh;
  if (!subscription.endpoint || !authKey || !p256dhKey) {
    throw new Error('The browser did not return a complete push subscription.');
  }

  const deviceName = [
    navigator.platform,
    /Edg\//.test(navigator.userAgent) ? 'Edge' : /Chrome\//.test(navigator.userAgent) ? 'Chrome' : 'Browser',
  ].filter(Boolean).join(' · ').slice(0, 120);
  const now = new Date().toISOString();
  const [{ error: subscriptionError }, { error: preferenceError }] = await Promise.all([
    supabase
      .from('push_subscriptions')
      .upsert({
        user_id: userId,
        endpoint: subscription.endpoint,
        auth_key: authKey,
        p256dh_key: p256dhKey,
        enabled: true,
        device_name: deviceName,
        last_seen_at: now,
      }, { onConflict: 'endpoint' }),
    supabase
      .from('chat_notification_preferences')
      .upsert({ user_id: userId, desktop_push_enabled: true }, { onConflict: 'user_id' }),
  ]);
  if (subscriptionError) throw subscriptionError;
  if (preferenceError) throw preferenceError;

  return { supported: true, permission, enabled: true, configured: true };
}

// Backwards-compatible entry point used by older notification surfaces.
export async function requestPushNotifications(userId: string): Promise<NotificationPermission> {
  const state = await setChatPushNotifications(userId, true);
  return state.permission === 'unsupported' ? 'denied' : state.permission;
}

export interface Notification {
  id: string;
  user_id: string;
  type: string;
  category: string;
  title: string;
  message: string;
  data: any;
  read: boolean;
  created_at: string;
}

export function useNotifications() {
  const { user } = useAuth();
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);

  const fetchNotifications = async () => {
    if (!user) return;
    const { data, error } = await supabase
      .from('notifications')
      .select('*')
      .eq('user_id', user.id)
      .order('created_at', { ascending: false })
      .limit(50);
    if (error) {
      console.error('Error fetching notifications:', error);
      return;
    }
    setNotifications((data || []) as Notification[]);
    setUnreadCount((data || []).filter((notification) => !notification.read).length);
  };

  useEffect(() => {
    if (!user) return;
    void fetchNotifications();
    const channel = supabase
      .channel(`notifications:${user.id}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'notifications',
        filter: `user_id=eq.${user.id}`,
      }, () => void fetchNotifications())
      .subscribe();
    return () => {
      void supabase.removeChannel(channel);
    };
  }, [user?.id]);

  const markAsRead = async (id: string) => {
    if (!user) return;
    const { error } = await supabase
      .from('notifications')
      .update({ read: true })
      .eq('id', id)
      .eq('user_id', user.id);
    if (error) return console.error('Error marking notification as read:', error);
    setNotifications((current) => current.map((notification) => (
      notification.id === id ? { ...notification, read: true } : notification
    )));
    setUnreadCount((current) => Math.max(0, current - 1));
  };

  const markAllAsRead = async () => {
    if (!user) return;
    const { error } = await supabase
      .from('notifications')
      .update({ read: true })
      .eq('user_id', user.id)
      .eq('read', false);
    if (error) return console.error('Error marking all notifications as read:', error);
    setNotifications((current) => current.map((notification) => ({ ...notification, read: true })));
    setUnreadCount(0);
  };

  return {
    notifications,
    unreadCount,
    markAsRead,
    markAllAsRead,
    requestPermission: () => user
      ? requestPushNotifications(user.id)
      : Promise.resolve('denied' as NotificationPermission),
  };
}
